state.cold_header:
#ifndef W1700K_NPU_COLD_SETUP_H
#define W1700K_NPU_COLD_SETUP_H

#include "bootstrap.h"
#include "control-v2.h"

#define NPU_COLD_REQUEST 0x3253434eu /* NCS2 */
#define NPU_COLD_REPLY 0x3252434eu /* NCR2 */
#define NPU_COLD_VERSION 2u
#define NPU_COLD_SIZE 80u
#define NPU_COLD_API 1u
#define NPU_COLD_PENDING_OPERATION 4u
#define NPU_COLD_PORT 1u
#define NPU_COLD_RX0 2u
#define NPU_COLD_RX2 4u
#define NPU_COLD_ENDPOINT_BASE 8u
#define NPU_COLD_ENDPOINT_BYTES 16u
#define NPU_COLD_ADDR5 32u
#define NPU_COLD_PAGE5 64u
#define NPU_COLD_ADDR6 128u
#define NPU_COLD_PAGE6 256u
#define NPU_COLD_ADDR7 512u
#define NPU_COLD_PAGE7 1024u
#define NPU_COLD_COMPLETED_MASK 2047u
#define NPU_COLD_BIND_HEADER 0x1fu
#define NPU_COLD_BIND_BASE_API 0x100u
#define NPU_COLD_BIND_BYTES_API 0x101u
#define NPU_COLD_PAGE_REG0 0xd45a0u
#define NPU_COLD_ENDPOINT_MIN_BYTES (NPU_COLD_PAGE_REG0 + 0x20u + 12u)

static inline int npu_cold_endpoint_valid(uint32_t base, uint32_t bytes)
{
    return base && !(base & 4095u) && base < 0xc0000000u &&
           bytes >= NPU_COLD_ENDPOINT_MIN_BYTES && !(bytes & 4095u) &&
           bytes <= 0xc0000000u - base;
}

enum npu_cold_status {
    NPU_COLD_OK,
    NPU_COLD_BAD_MESSAGE,
    NPU_COLD_BAD_BOOT,
    NPU_COLD_BAD_SESSION,
    NPU_COLD_REPLAY,
    NPU_COLD_BAD_STATE,
    NPU_COLD_UNSUPPORTED,
    NPU_COLD_CALLBACK_FAILED,
};

struct npu_cold_packet {
    uint32_t header, api, magic, version, bytes;
    uint32_t epoch, sequence;
    uint32_t nonce_lo, nonce_hi, boot_lo, boot_hi;
    struct npu_bootstrap_packet command;
    uint32_t status, reserved[5];
};

/* Fixed byte access also avoids an unavailable libc call in the raw RV32 build. */
static inline void npu_cold_packet_copy(struct npu_cold_packet *destination,
                                       const struct npu_cold_packet *source)
{
    volatile unsigned char *to = (volatile void *)destination;
    const volatile unsigned char *from = (const volatile void *)source;
    uint32_t i;

    for (i = 0; i < NPU_COLD_SIZE; i++)
        to[i] = from[i];
}

/* Fresh native storage belongs to the boot, not each host attachment. A failed
 * callback retains inflight/active state; no API resets or retires this owner.
 * This is a software cold lane, not physical containment or release authority.
 */
struct npu_cold_setup {
    uint32_t failed, inflight, completed, sequence;
    uint32_t boot_lo, boot_hi, nonce_lo, nonce_hi, prior_completed;
    struct npu_bootstrap_packet command;
    uint32_t endpoint_base, endpoint_bytes, prior_base, prior_bytes;
};

enum npu_cold_status npu_cold_setup_begin(struct npu_cold_setup *setup,
    struct npu_control_v2_session *session, struct npu_admission *admission,
    struct npu_barrier *barrier, const struct npu_bootstrap *bootstrap,
    const struct npu_cold_packet *packet, uint32_t bytes);
enum npu_cold_status npu_cold_setup_finish(struct npu_cold_setup *setup,
    struct npu_control_v2_session *session, struct npu_admission *admission,
    struct npu_barrier *barrier, const struct npu_bootstrap *bootstrap,
    uint32_t callback_result, const struct npu_bootstrap_packet *reply);

uint32_t npu_cold_client_request(struct npu_control_v2_client *client,
    void *packet, uint32_t bytes, const struct npu_bootstrap_packet *command);
enum npu_client_result npu_cold_client_complete(struct npu_control_v2_client *client,
    uint32_t ticket, int transport_error, const void *packet, uint32_t bytes,
    const struct npu_bootstrap_packet *command, uint32_t *value);

#endif

state.cold_server:
#include "cold-setup.h"

_Static_assert(sizeof(struct npu_cold_packet) == NPU_COLD_SIZE, "cold wire changed");
_Static_assert(sizeof(struct npu_cold_setup) == 64, "cold owner changed");

static uint32_t load(const uint32_t *word)
{
    return __atomic_load_n(word, __ATOMIC_ACQUIRE);
}

static int held(const struct npu_admission *a, const struct npu_barrier *b,
                const struct npu_bootstrap *boot, uint32_t active)
{
    uint32_t i;

    if (a->closed != 1 || a->active != active || a->fault ||
        !(a->nonce_lo || a->nonce_hi) || load(&b->request) != 1 ||
        load(&b->fault) || load(&b->prepared) || load(&b->released) || load(&b->armed) ||
        boot->magic != NPU_BOOTSTRAP_MAGIC || boot->failed || boot->inflight ||
        boot->step != NPU_BOOTSTRAP_STEPS || boot->retained_mask != 0x1e)
        return 0;
    for (i = 0; i < NPU_BARRIER_WORKERS; i++)
        if (load(&b->parked[i]) != 1 || load(&b->ready[i]))
            return 0;
    for (i = 0; i < NPU_BARRIER_DOMAINS; i++)
        if (load(&b->drained[i]))
            return 0;
    for (i = 0; i < NPU_ADMISSION_IRQ_WORDS; i++)
        if (a->deferred[i])
            return 0;
    return 1;
}

static enum npu_cold_status fail(struct npu_cold_setup *s,
    struct npu_admission *a, struct npu_barrier *b, enum npu_cold_status error)
{
    s->failed = 1;
    npu_admission_fail(a, b);
    return error;
}

static int window(uint32_t base, uint32_t bytes, const struct npu_bootstrap *boot)
{
    uint32_t i;

    if (!npu_cold_endpoint_valid(base, bytes))
        return 0;
    for (i = 0; i < NPU_BOOT_REGIONS; i++) {
        const struct npu_bootstrap_range *r = &boot->plan.region[i];

        if (r->bytes && base < r->base + r->bytes && r->base < base + bytes)
            return 0;
    }
    return 1;
}

static int history(const struct npu_cold_setup *s, const struct npu_bootstrap *boot)
{
    static const uint32_t prefixes[] = {0, 8, 24, 25, 27, 31, 63, 127, 255, 511, 1023, 2047};
    uint32_t i;

    for (i = 0; i < sizeof(prefixes) / sizeof(prefixes[0]); i++)
        if (s->completed == prefixes[i])
            break;
    if (i == sizeof(prefixes) / sizeof(prefixes[0]))
        return 0;
    if (!(s->completed & NPU_COLD_ENDPOINT_BASE))
        return !s->endpoint_base && !s->endpoint_bytes;
    if (!s->endpoint_base || (s->endpoint_base & 4095u) || s->endpoint_base >= 0xc0000000u)
        return 0;
    return s->completed & NPU_COLD_ENDPOINT_BYTES ?
           window(s->endpoint_base, s->endpoint_bytes, boot) : !s->endpoint_bytes;
}

static uint32_t command_bit(const struct npu_bootstrap_packet *p,
                            const struct npu_cold_setup *s, const struct npu_bootstrap *boot)
{
    static const uint32_t limits[] = {256, 512, 1024};
    uint32_t i;

    if (p->header == NPU_COLD_BIND_HEADER && p->api == NPU_COLD_BIND_BASE_API &&
        p->value && !(p->value & 4095u) && p->value < 0xc0000000u)
        return NPU_COLD_ENDPOINT_BASE;
    if (p->header == NPU_COLD_BIND_HEADER && p->api == NPU_COLD_BIND_BYTES_API &&
        window(s->endpoint_base, p->value, boot))
        return NPU_COLD_ENDPOINT_BYTES;
    if (p->header == 0x10 && p->api == 14 && p->value == 2)
        return NPU_COLD_PORT;
    if (p->header == 0x10 && p->api == 1 && p->value && p->value <= 1536)
        return NPU_COLD_RX0;
    if (p->header == 0x12 && p->api == 1 && p->value && p->value <= 1024)
        return NPU_COLD_RX2;
    for (i = 0; i < 3; i++) {
        if (p->header != 0x15u + i)
            continue;
        if (p->api == 0 && window(s->endpoint_base, s->endpoint_bytes, boot) &&
            p->value == s->endpoint_base + NPU_COLD_PAGE_REG0 + 0x10u * i)
            return NPU_COLD_ADDR5 << (i * 2);
        if (p->api == 1 && p->value && p->value <= limits[i])
            return NPU_COLD_PAGE5 << (i * 2);
    }
    return 0;
}

static uint32_t prior(uint32_t bit)
{
    switch (bit) {
    case NPU_COLD_ENDPOINT_BASE: return 0;
    case NPU_COLD_ENDPOINT_BYTES: return NPU_COLD_ENDPOINT_BASE;
    case NPU_COLD_PORT: return NPU_COLD_ENDPOINT_BASE | NPU_COLD_ENDPOINT_BYTES;
    case NPU_COLD_RX0: return 25;
    case NPU_COLD_RX2: return 27;
    default: return bit - 1;
    }
}

enum npu_cold_status npu_cold_setup_begin(struct npu_cold_setup *s,
    struct npu_control_v2_session *session, struct npu_admission *a,
    struct npu_barrier *b, const struct npu_bootstrap *boot,
    const struct npu_cold_packet *packet, uint32_t bytes)
{
    struct npu_cold_packet p;
    uint32_t i, bit;

    if (!packet || bytes != sizeof(p))
        return NPU_COLD_BAD_MESSAGE;
    npu_cold_packet_copy(&p, packet);
    if (p.header != NPU_CONTROL_HEADER || p.api != NPU_COLD_API ||
        p.magic != NPU_COLD_REQUEST || p.version != NPU_COLD_VERSION ||
        p.bytes != sizeof(p) || !p.sequence || p.status)
        return NPU_COLD_BAD_MESSAGE;
    for (i = 0; i < 5; i++)
        if (p.reserved[i])
            return NPU_COLD_BAD_MESSAGE;
    if (!(session->boot_lo || session->boot_hi) ||
        p.boot_lo != session->boot_lo || p.boot_hi != session->boot_hi)
        return NPU_COLD_BAD_BOOT;
    if (!(session->nonce_lo || session->nonce_hi) ||
        p.nonce_lo != session->nonce_lo || p.nonce_hi != session->nonce_hi ||
        a->nonce_lo != session->nonce_lo || a->nonce_hi != session->nonce_hi)
        return NPU_COLD_BAD_SESSION;
    if (p.sequence <= session->last_sequence)
        return NPU_COLD_REPLAY;
    /* Reserve before platform/command checks: abandonment never enables replay. */
    session->last_sequence = p.sequence;
    if (s->failed || s->inflight || !history(s, boot) ||
        p.epoch != 1 || !held(a, b, boot, 0))
        return fail(s, a, b, NPU_COLD_BAD_STATE);
    bit = command_bit(&p.command, s, boot);
    if (!bit && !(p.command.header == 0x30 && p.command.api == 10 && !p.command.value))
        return fail(s, a, b, NPU_COLD_UNSUPPORTED);
    if (bit && s->completed != prior(bit))
        return fail(s, a, b, NPU_COLD_BAD_STATE);
    s->command = p.command;
    s->sequence = p.sequence;
    s->boot_lo = p.boot_lo;
    s->boot_hi = p.boot_hi;
    s->nonce_lo = p.nonce_lo;
    s->nonce_hi = p.nonce_hi;
    s->prior_completed = s->completed;
    s->prior_base = s->endpoint_base;
    s->prior_bytes = s->endpoint_bytes;
    s->inflight = a->active = 1;
    return NPU_COLD_OK;
}

enum npu_cold_status npu_cold_setup_finish(struct npu_cold_setup *s,
    struct npu_control_v2_session *session, struct npu_admission *a,
    struct npu_barrier *b, const struct npu_bootstrap *boot,
    uint32_t result, const struct npu_bootstrap_packet *reply)
{
    uint32_t bit = command_bit(&s->command, s, boot);

    if (s->failed || s->inflight != 1 || !held(a, b, boot, 1) ||
        session->last_sequence != s->sequence ||
        session->boot_lo != s->boot_lo || session->boot_hi != s->boot_hi ||
        session->nonce_lo != s->nonce_lo || session->nonce_hi != s->nonce_hi ||
        a->nonce_lo != s->nonce_lo || a->nonce_hi != s->nonce_hi ||
        s->completed != s->prior_completed || s->endpoint_base != s->prior_base ||
        s->endpoint_bytes != s->prior_bytes || !history(s, boot) ||
        (bit && s->completed != prior(bit)) ||
        (!bit && !(s->command.header == 0x30 && s->command.api == 10 && !s->command.value)) ||
        !reply || result != 1 || reply->header != s->command.header ||
        reply->api != s->command.api ||
        reply->value != (bit ? s->command.value : 0x457u))
        return fail(s, a, b, NPU_COLD_CALLBACK_FAILED);
    if (bit == NPU_COLD_ENDPOINT_BASE)
        s->endpoint_base = s->command.value;
    if (bit == NPU_COLD_ENDPOINT_BYTES)
        s->endpoint_bytes = s->command.value;
    s->completed |= bit;
    s->inflight = a->active = 0;
    return NPU_COLD_OK;
}

state.native_adapter:
/* Raw native cold-command binding; physical backing/drains remain unproved. */
#include "cold-setup.h"

extern struct npu_bootstrap npu_emulation_bootstrap_state;
extern struct npu_control_v2_session npu_emulation_control_v2_state;
extern struct npu_admission npu_emulation_admission_state;
extern struct npu_barrier npu_emulation_barrier_state;
struct npu_cold_setup npu_emulation_cold_setup_state;

typedef uint32_t (*native_callback)(struct npu_bootstrap_packet *);

int npu_emulation_cold_mailbox(struct npu_cold_packet *host, uint32_t bytes)
{
    struct npu_cold_packet snapshot;
    struct npu_cold_setup *s = &npu_emulation_cold_setup_state;
    struct npu_bootstrap_packet command;
    enum npu_cold_status status;
    uint32_t callback, slot, result = 0;

    if (bytes != sizeof(snapshot))
        return 0;
    npu_cold_packet_copy(&snapshot, host);
    status = npu_cold_setup_begin(s, &npu_emulation_control_v2_state,
        &npu_emulation_admission_state, &npu_emulation_barrier_state,
        &npu_emulation_bootstrap_state, &snapshot, bytes);
    if (status == NPU_COLD_OK) {
        command.header = s->command.header;
        command.api = s->command.api;
        command.value = s->command.value;
        if (command.header == NPU_COLD_BIND_HEADER) {
            result = 1;
            slot = callback = 0;
        } else if (command.header == 0x30) {
            slot = 0x3e900170u;
            callback = 0x840101a6u;
        } else {
            slot = 0x3e900178u + command.api * 4;
            callback = command.api == 14 ? 0x8400ff34u :
                       command.api == 0 ? 0x8400fdc4u : 0x8400fe34u;
        }
        if (slot && *(const volatile uint32_t *)(uintptr_t)slot == callback)
            result = ((native_callback)(uintptr_t)callback)(&command);
        status = npu_cold_setup_finish(s, &npu_emulation_control_v2_state,
            &npu_emulation_admission_state, &npu_emulation_barrier_state,
            &npu_emulation_bootstrap_state, result, &command);
        if (status == NPU_COLD_OK)
            snapshot.command.value = command.value;
    }
    snapshot.magic = NPU_COLD_REPLY;
    snapshot.status = status;
    npu_cold_packet_copy(host, &snapshot);
    return 1;
}

state.page_callback:
uint32_t npu_emulation_page_callback(const struct npu_bootstrap_packet *packet)
{
    uint32_t selector = packet->header & 15, status, result = 0, ready;
    struct npu_bootstrap_packet snapshot;
    static const uint32_t limits[3] = {256, 512, 1024};
    static const uint32_t flags[3] = {0x3e901f44u, 0x3e903954u, 0x3e902ce8u};

    if (selector < 5 || selector > 7)
        return npu_emulation_txdone_callback(packet);
    __asm__ volatile ("csrrci %0, mstatus, 8" : "=r"(status) :: "memory");
    snapshot = *packet;
    ready = flags[selector - 5];
    if (selector == 5 && snapshot.header == 0x15 && snapshot.api == 1 &&
        snapshot.value && snapshot.value <= limits[0] &&
        !load(&npu_emulation_page_state.magic) &&
        npu_emulation_page_init() != NPU_COLD_PAGE_OK) {
        fail();
        goto done;
    }
    if (snapshot.header != (0x10u | selector) || snapshot.api != 1 ||
        !snapshot.value || snapshot.value > limits[selector - 5] || busy ||
        !live() || word(ready) || load(&npu_emulation_page_state.fault) ||
        load(&npu_emulation_page_state.magic) != NPU_COLD_PAGE_MAGIC) {
        fail();
        goto done;
    }
    busy = 1;
    result = !npu_original_page_dispatch(snapshot.value, selector);
    if (!result || !live() || load(&npu_emulation_page_state.fault) || word(ready) != 1) {
        fail();
        *(volatile uint32_t *)(uintptr_t)ready = 0;
        result = 0;
    }
    busy = 0;
done:
    __asm__ volatile ("csrw mstatus, %0" :: "r"(status) : "memory");
    return result;
}

state.executor_source:
#include <linux/errno.h>
#include <linux/soc/airoha/airoha_offload.h>
#include "linux-control.h"

_Static_assert(sizeof(struct npu_control_v2_packet) == NPU_CONTROL_V2_SIZE,
	       "control packet layout changed");

static int hold(struct npu_linux_control *control, int error)
{
	if (!control->error)
		control->error = error;
	npu_client_v2_abort(&control->client);
	return control->error;
}

int npu_linux_control_init(struct npu_linux_control *control,
			   struct airoha_npu *provider, u32 nonce_lo, u32 nonce_hi)
{
	if (!control)
		return -EINVAL;
	if (control->initialized)
		return -EALREADY;

	mutex_init(&control->mutex);
	control->provider = provider;
	control->error = 0;
	control->closed = false;
	npu_client_v2_init(&control->client, nonce_lo, nonce_hi);
	control->initialized = true;
	if (!provider || control->client.base.phase == NPU_CLIENT_FAILED) {
		control->provider = NULL;
		control->closed = true;
		return hold(control, provider ? -EINVAL : -ENODEV);
	}
	return 0;
}

static int next_operation(const struct npu_linux_control *control)
{
	switch (control->client.base.phase) {
	case NPU_CLIENT_NEW:
		return NPU_CONTROL_DISCOVER;
	case NPU_CLIENT_DISCOVERED:
		return NPU_CONTROL_BIND;
	case NPU_CLIENT_BOUND:
		return NPU_CONTROL_STOP;
	case NPU_CLIENT_STOPPING:
	case NPU_CLIENT_PARKED:
		return NPU_CONTROL_STATUS;
	default:
		return -EINVAL;
	}
}

int npu_linux_control_exchange(struct npu_linux_control *control,
			       enum npu_control_operation operation)
{
	struct npu_control_v2_packet packet;
	enum npu_client_result result;
	u32 ticket;
	int error;

	if (!control || !control->initialized)
		return -EINVAL;
	mutex_lock(&control->mutex);
	if (control->error) {
		error = control->error;
		goto unlock;
	}
	if (control->closed || !control->provider) {
		error = hold(control, -ESHUTDOWN);
		goto unlock;
	}
	/* A repeated BIND must never silently turn into the client's next STOP. */
	if (next_operation(control) != (int)operation) {
		error = hold(control, -EINVAL);
		goto unlock;
	}
	ticket = npu_client_v2_request(&control->client, &packet, sizeof(packet));
	if (!ticket) {
		error = hold(control, -EPROTO);
		goto unlock;
	}
	/* Firmware uses the provider's coherent copy, including after a timeout.
	 * This synchronous call never retains the address of the stack packet.
	 */
	error = airoha_npu_wlan_control(control->provider, &packet, sizeof(packet));
	result = npu_client_v2_complete(&control->client, ticket, error,
				       &packet, sizeof(packet));
	if (error || result != NPU_CLIENT_ACCEPTED)
		error = hold(control, error < 0 ? error : error ? -EIO : -EPROTO);
unlock:
	mutex_unlock(&control->mutex);
	return error;
}

int npu_linux_control_snapshot(struct npu_linux_control *control,
			       struct npu_linux_control_snapshot *snapshot)
{
	if (!control || !control->initialized || !snapshot)
		return -EINVAL;
	mutex_lock(&control->mutex);
	snapshot->client = control->client;
	snapshot->error = control->error;
	snapshot->closed = control->closed;
	mutex_unlock(&control->mutex);
	return 0;
}

int npu_linux_control_cold_exchange(struct npu_linux_control *control,
				    const struct npu_bootstrap_packet *command,
				    u32 *value)
{
	struct npu_bootstrap_packet snapshot;
	struct npu_cold_packet packet;
	enum npu_client_result result;
	u32 ticket;
	int error;

	if (!control || !control->initialized || !command || !value)
		return -EINVAL;
	mutex_lock(&control->mutex);
	if (control->error) {
		error = control->error;
		goto unlock;
	}
	if (control->closed || !control->provider) {
		error = hold(control, -ESHUTDOWN);
		goto unlock;
	}
	snapshot = *command;
	ticket = npu_cold_client_request(&control->client, &packet,
					 sizeof(packet), &snapshot);
	if (!ticket) {
		error = hold(control, -EPROTO);
		goto unlock;
	}
	error = airoha_npu_wlan_control(control->provider, &packet, sizeof(packet));
	result = npu_cold_client_complete(&control->client, ticket, error,
					  &packet, sizeof(packet), &snapshot, value);
	if (error || result != NPU_CLIENT_ACCEPTED)
		error = hold(control, error < 0 ? error : error ? -EIO : -EPROTO);
unlock:
	mutex_unlock(&control->mutex);
	return error;
}

void npu_linux_control_close(struct npu_linux_control *control)
{
	if (!control || !control->initialized)
		return;
	mutex_lock(&control->mutex);
	hold(control, -ESHUTDOWN);
	control->closed = true;
	control->provider = NULL;
	mutex_unlock(&control->mutex);
}
